const load=():Custom=>{try{const parsed=JSON.parse(localStorage.getItem('france-budget-v1')||'{}');return {...defaults,...parsed,revenues:parsed.revenues??{},expenses:parsed.expenses??{},offBudget:parsed.offBudget??{}}}catch{return defaults}};
const numeric=(n:number)=>Math.round(n*10)/10;
function InfoHint({item}:{item:Category}){return <span className="info-hint" tabIndex={0} role="note" aria-label={item.label+' : '+item.description} title={item.description}><Info size={13}/><span className="info-tooltip">{item.description}<small>Référentiel : {item.canonical}</small></span></span>}
function ImpactTags({revenueDelta=0,expenseDelta=0}:{revenueDelta?:number;expenseDelta?:number}){return <span className="measure-impact-tags">{revenueDelta!==0&&<em className="impact-tag revenue">Recettes · {revenueDelta>0?'Hausse':'Baisse'} de {currency(Math.abs(revenueDelta))}</em>}{expenseDelta!==0&&<em className="impact-tag expense">Dépenses · {expenseDelta>0?'Hausse':'Baisse'} de {currency(Math.abs(expenseDelta))}</em>}{revenueDelta===0&&expenseDelta===0&&<em className="impact-tag">Impact non chiffré</em>}</span>}
function MaturityTag({budget}:{budget:BudgetMaturity}){const maturity=budgetMaturity(budget);return maturity?<span className={'budget-maturity budget-maturity--'+maturity.tone} title={maturity.description} aria-label={'Maturité des données : '+maturity.label+'. '+maturity.description}>{maturity.label}</span>:null}
function Pill({children}:{children:React.ReactNode}){return <span className="pill">{children}</span>}
function Stat({label,value,tone,subtitle}:{label:string;value:string;tone?:string;subtitle?:string}){return <div className="stat"><span className="eyebrow">{label}</span><strong className={tone||''}>{value}</strong>{subtitle&&<small>{subtitle}</small>}</div>}
function Gauge({item,value,onChange,tone,editing,kind}:{item:Category;value:number;onChange:(v:number)=>void;tone:'green'|'coral';editing:boolean;kind:string;scaleMax:number}){const max=Math.max(item.amount*2,1);return <div className="slider-item"><div className="slider-label"><label htmlFor={kind+'-'+item.id}>{item.label} <InfoHint item={item}/></label><strong>{currency(value)}</strong></div><div className="gauge-container"><div className="gauge-track"><div className={'gauge-fill '+tone} style={{width:Math.min(100,value/max*100)+'%'}}/></div>{editing&&<input aria-label={'Modifier '+item.label} id={kind+'-'+item.id} className="gauge-input" type="range" min="0" max={max} step="0.1" value={value} onChange={e=>onChange(+e.target.value)}/>}</div><span className="muted tiny">Référence {currency(item.amount)}{value!==item.amount?' · Écart '+(value>item.amount?'+':'')+currency(numeric(value-item.amount)):''}</span></div>}
function ComparisonBars({items,values,tone}:{items:Category[];values?:Record<string,number>;tone:'green'|'coral'}){const max=Math.max(...items.map(x=>Math.max(x.amount,values?.[x.id]??x.amount)),1);return <div className="bar-list">{items.filter(x=>x.amount>0).map(item=>{const v=values?.[item.id]??item.amount;return <div className="bar-item" key={item.id}><div className="bar-head"><span>{item.label} <InfoHint item={item}/></span><span>{currency(v)}</span></div><div className="bar-track"><div className={'bar-fill '+tone} style={{width:Math.max(0,100*item.amount/max)+'%'}}></div>{values&&<div className="bar-marker" style={{left:Math.min(100,Math.max(0,100*v/max))+'%'}}/>}</div></div>})}</div>}
